-- NM-CATALOG-KOLBENSCHMIDT-OFFICIAL-FITMENT-IMPORT
-- Official MS Motorservice snapshot, captured 2026-07-25 from source data as of 2026-07-22.
-- Weight, origin, HS code and incomplete OEM are intentionally not populated.

alter table public.catalog_product_fitments add column if not exists fitment_type text not null default 'vehicle';
alter table public.catalog_product_fitments add column if not exists charging_type text;
alter table public.catalog_product_fitments add column if not exists cylinder_count integer;
alter table public.catalog_product_fitments add column if not exists valve_count integer;
alter table public.catalog_product_fitments add column if not exists bore_mm numeric;
alter table public.catalog_product_fitments add column if not exists stroke_mm numeric;
alter table public.catalog_product_fitments add column if not exists displacement_cc numeric;
alter table public.catalog_product_fitments add column if not exists compression_ratio numeric;
alter table public.catalog_product_fitments drop constraint if exists catalog_product_fitments_type_check;
alter table public.catalog_product_fitments add constraint catalog_product_fitments_type_check check (fitment_type in ('vehicle','engine'));
create index if not exists idx_catalog_product_fitments_type on public.catalog_product_fitments (organization_id,catalog_product_id,fitment_type);

do $body$
declare v_org uuid; v_product uuid; v_source uuid;
begin
 select p.organization_id,p.id into v_org,v_product from public.catalog_products p join public.brands b on b.id=p.brand_id where lower(b.name)='kolbenschmidt' and public.normalize_part_code(p.product_code)=public.normalize_part_code('40 448 601') limit 1;
 if v_product is null then raise exception 'Kolbenschmidt target product not found'; end if;
 insert into public.catalog_product_source_records(organization_id,catalog_product_id,source_key,source_url,source_product_id,source_version,source_product_type,source_as_of,payload_fingerprint) values(v_org,v_product,'motorservice-msicd','https://onlineshop.ms-motorservice.com/msi/MSICD?lang=E&page=showKODetail&ksnr=40448601&stacklevel=0&hisdir=fwd','40448601','3.0.0 / 2746','Kolben','2026-07-22'::date,'c04e8500554305adf4bfd3adf56612a1aef159e2a5bfd62fd3ff989ce0079cca') on conflict (organization_id,catalog_product_id,source_key,payload_fingerprint) do update set retrieved_at=now() returning id into v_source;
 insert into public.catalog_product_identifiers(organization_id,catalog_product_id,identifier_type,authority,value,source_record_id) values(v_org,v_product,'casting_number','MS Motorservice','130 116',v_source) on conflict do nothing;
 insert into public.catalog_product_attributes(organization_id,catalog_product_id,attribute_key,label,value_text,value_numeric,unit,source_record_id) values
 (v_org,v_product,'cylinder_diameter','Cylinder diameter',null,130.0,'mm',v_source),
 (v_org,v_product,'compression_height','Compression height',null,78.55,'mm',v_source),
 (v_org,v_product,'bowl_depth','Bowl depth',null,16.5,'mm',v_source),
 (v_org,v_product,'bowl_diameter','Bowl diameter',null,92.8,'mm',v_source),
 (v_org,v_product,'total_length','Total length',null,123.55,'mm',v_source),
 (v_org,v_product,'pin_diameter','Pin diameter',null,52.0,'mm',v_source),
 (v_org,v_product,'pin_length','Pin length',null,103.0,'mm',v_source),
 (v_org,v_product,'conrod_design','Conrod design','trapezoidal connecting rod',null,null,v_source),
 (v_org,v_product,'piston_protrusion','Piston protrusion','0.27 to 0.61',null,'mm',v_source),
 (v_org,v_product,'piston_designs','Piston designs','RTK, KKK, KBB',null,null,v_source)
 on conflict (organization_id,catalog_product_id,attribute_key,ordinal) do update set value_numeric=excluded.value_numeric,value_text=excluded.value_text,unit=excluded.unit,source_record_id=excluded.source_record_id;
 update public.catalog_product_attributes set value_text=case attribute_key when 'conrod_design' then 'trapezoidal connecting rod' when 'piston_protrusion' then '0.27 to 0.61' when 'piston_designs' then 'RTK, KKK, KBB' end where organization_id=v_org and catalog_product_id=v_product and attribute_key in ('conrod_design','piston_protrusion','piston_designs');
 insert into public.catalog_product_fitments(organization_id,catalog_product_id,fitment_type,manufacturer,model_series,vehicle,model_year_from,model_year_to,engine_code,fuel_type,power_kw_min,power_kw_max,power_ps_min,power_ps_max,source_record_id,fitment_fingerprint) select v_org,v_product,'vehicle',x.manufacturer,x.model_series,x.vehicle,x.model_year_from,x.model_year_to,x.engine_code,x.fuel_type,x.power_kw_min,x.power_kw_max,x.power_ps_min,x.power_ps_max,v_source,x.fingerprint from jsonb_to_recordset($jsonveh$[{"source_row":1,"manufacturer":"IHC-CASE (CNH)","model_series":"SERIES 7000","vehicle":"Series 7800","model_year_from":"01.1998","model_year_to":null,"engine_code":"OM 942.967 Euro 2","fuel_type":"D","power_kw_min":370,"power_kw_max":380,"power_ps_min":503,"power_ps_max":517,"fingerprint":"63d7a91c6cc9b991bf0859829b4a5a578e9c94659e49e2ceffbbf34860cd0339"},{"source_row":2,"manufacturer":"MERCEDES-BENZ","model_series":"ACTROS MP2 / MP3","vehicle":"1831","model_year_from":"11.2002","model_year_to":null,"engine_code":"OM 541.920 Euro 2","fuel_type":"D","power_kw_min":230,"power_kw_max":230,"power_ps_min":313,"power_ps_max":313,"fingerprint":"df3f8e94226358b37f46fcfcd62f2a2697491d174f8537720bc460b7791d91ce"},{"source_row":3,"manufacturer":"MERCEDES-BENZ","model_series":"ACTROS MP2 / MP3","vehicle":"1831","model_year_from":"11.2002","model_year_to":null,"engine_code":"OM 541.940 Euro 2/3","fuel_type":"D","power_kw_min":230,"power_kw_max":235,"power_ps_min":313,"power_ps_max":320,"fingerprint":"a089398b8bcecd3781d006ba1d61bfa110eb8811d1bb984042509e37bd07a6af"},{"source_row":4,"manufacturer":"MERCEDES-BENZ","model_series":"ACTROS MP2 / MP3","vehicle":"1831 AK","model_year_from":"04.2003","model_year_to":null,"engine_code":"OM 541.926 Euro 2","fuel_type":"D","power_kw_min":230,"power_kw_max":230,"power_ps_min":313,"power_ps_max":313,"fingerprint":"015b99483f3a8427d4b8fdc5ac98ff7885bcf09171e6318a48dacd835372e9d6"},{"source_row":5,"manufacturer":"MERCEDES-BENZ","model